"""150 editorial relationship hooks; no runtime people or faction entities."""
import json
from pathlib import Path
from encounter_helpers import ids

BASE = Path(__file__).resolve().parents[1]
EVENTS = {e["encounter_id"]: e for p in (BASE / "encounters").glob("*.json")
          for e in json.loads(p.read_text(encoding="utf-8"))}
TOWNS = {"new_hope": "新希望", "gray_valley": "灰谷", "dry_well": "乾井"}
GROUPS = {
    "new_hope": {"W": "nh_water_stewards", "G": "nh_growers", "C": "nh_clinic", "N": "nh_newcomers"},
    "gray_valley": {"Y": "gv_yard_workers", "W": "gv_workshops", "B": "gv_salvage_buyers", "R": "gv_residents"},
    "dry_well": {"F": "dw_fuel_cooperative", "B": "dw_caravan_brokers", "W": "dw_well_queue", "C": "dw_outer_camps"},
}


def make(town, text):
    rows = []
    for line in text.strip().splitlines():
        if not line.strip():
            continue
        fields = line.split("|")
        assert len(fields) == 14, (town, len(fields), line)
        number, role, groups, need, stake, leverage, limit, item_names, event_names, target, tension, cooperation, available, absent = fields
        eid = event_names.split(",")
        for ref in eid:
            assert ref in EVENTS, ref
        dependencies = {"item_ownership", "npc_relationship", "jobs", "knowledge"}
        refs = {"WG-04", "LD-P02"}
        for ref in eid:
            dependencies.update(EVENTS[ref]["dependencies"])
            refs.update(EVENTS[ref]["inspiration_refs"])
        rows.append({
            "hook_id": f"hook_{town}_{number}", "town_id": town, "status": "DESIGN_ONLY",
            "role_zh": role, "public_need_zh": need, "private_stake_zh": stake,
            "leverage_zh": leverage, "limit_zh": limit,
            "group_ids": [GROUPS[town][g] for g in groups.split(",")],
            "binding_zh": f"未來從{TOWNS[town]}當前在場且存活的人口中，確認有意願承擔『{role}』職責者後綁定；若需具名化只能標記既有人口。這是角色候選，可由同一既有人物兼任相容職責，不新增總人口或自動生成家屬。接受與提交時重驗在場、存活、職責與同意。",
            "item_refs": ids(item_names), "encounter_refs": eid,
            "relationships": [{"target_hook_id": f"hook_{town}_{target}", "tension_zh": tension, "cooperation_zh": cooperation}],
            "availability": {"condition_zh": available, "without_player_zh": absent},
            "dependencies": sorted(dependencies), "inspiration_refs": sorted(refs),
        })
    assert len(rows) == 50 and {r["hook_id"] for r in rows} == {f"hook_{town}_{i:03}" for i in range(1, 51)}
    return rows


